// Warm-up ramps for the Connect Four lessons: `node tools/ramps.js` writes them into lessons.json (step.ramp + rampUi),
// `node tools/check_lessons.js` verifies them with the solver (engine.js).
// A ramp runs before a lesson's scored problems and is not scored:
//   {k:'explain', moves, seq?, marks:[[col,row,cls,label?]], t, body}   read-only; seq = the idea played out (numbered discs)
//   {k:'try', moves, ok:[cols], rule, look:[[col,row]], g, h, y}       any column in ok is right
// col 0..6 = a..g, row 0..5 from the bottom. rule (what the checker compares ok with):
//   'best'   = exactly the columns whose solver result (win / draw / loss) is the best one
//   'mate:n' = exactly the columns that force a four within n own moves, and none faster
// Hints go concept (h) → cells to look at (look) → the answer. %P1% / %P2% are the disc names of the current skin.
'use strict';
const fs = require('fs'), path = require('path');
const { keepLangs } = require(path.join(__dirname, '../../tools', 'keep-langs.js'));   // keeps ru / zh-TW / id / tr of unchanged texts
const FILE = path.join(__dirname, '..', 'lessons.json');
const L = (ja, en, zh, ko, es, fr, pt, de, hi, ar) => ({ ja, en, zh, ko, es, fr, pt, de, hi, ar });

